INSERT OR REPLACE INTO Language_en_US (Tag,Text) VALUES
('TXT_KEY_SOFT_KITTY_CIV','Trent - The Soft Kitty Serenader'),
('TXT_KEY_SOFT_KITTY_SHORT','Una Court (Soft Kitty)'),
('TXT_KEY_SOFT_KITTY_ADJECTIVE','Una Court'),
('TXT_KEY_SOFT_KITTY_LEADER','Trent'),
('TXT_KEY_SOFT_KITTY_TRAIT','Soft Kitty, Warm Kitty'),
('TXT_KEY_SOFT_KITTY_TRAIT_HELP','Serenade a met civilization at peace every 15 turns for Era-scaled Culture and Tourism. Friendly audiences double rewards; rejection causes temporary Repercussions. Your first rejection becomes The Ex.'),
('TXT_KEY_SOFT_KITTY_PEDIA','Una Court finds its strength in friendship, music and the occasional lesson in choosing an audience. Led by Trent, the Soft Kitty Serenader, its people turn diplomatic affection into Culture and Tourism.'),
('TXT_KEY_SOFT_KITTY_STRATEGY','Friendship is your strongest resource. Secure Declarations of Friendship for safe double-reward Serenades. Build Comfort Rooms before courting riskier audiences. Send Hopeless Romantics to foreign cities whose Culture is delaying your Cultural Victory.'),
('TXT_KEY_CIV5_SOFT_KITTY','Una Court'),
('TXT_KEY_CIV5_SOFT_KITTY_HEADING_1','A softer Una Court'),
('TXT_KEY_CIV5_SOFT_KITTY_TEXT_1','This incarnation of Trent pursues Culture, Tourism and Diplomacy through song. He rules as a civilization leader, with a normal starting army and no separate irreplaceable Trent unit. Navy banners, crowned cats and warm gold distinguish his court.'),
('TXT_KEY_CIV5_SOFT_KITTY_HEADING_2','Sing Soft Kitty'),
('TXT_KEY_CIV5_SOFT_KITTY_TEXT_2','Use the Sing Soft Kitty button to select a living major civilization you have met and are not at war with. A successful song grants 30 Culture and 20 Tourism against the target, multiplied by your Era index plus one. Cooldown is 15 turns on Standard speed and starts after every attempt, including rejection. Cooldown and recovery use game-speed TrainPercent; instant UA rewards use CulturePercent.[NEWLINE][NEWLINE]Friendly or Declaration of Friendship: 200% rewards, 0% risk.[NEWLINE]Neutral or Afraid: 100% rewards, 10% risk.[NEWLINE]Guarded or Deceptive: 75% rewards, 25% risk.[NEWLINE]Hostile: 50% rewards, 50% risk.[NEWLINE][NEWLINE]A successful song also grants 5 Influence with each City-State allied to the target. Failed UA songs grant no rewards.'),
('TXT_KEY_CIV5_SOFT_KITTY_HEADING_3','Repercussions and The Ex'),
('TXT_KEY_CIV5_SOFT_KITTY_TEXT_3','Rejection causes Repercussions for 5 Standard-speed turns: -15% Production in every city, -10% military Combat Strength, -20% Great Person generation, and no Sing Soft Kitty. Land and naval military units trained during recovery suffer -1 Movement until recovery ends. Purchased units and civilians are excluded. Repeated backlash refreshes the duration without stacking penalties.[NEWLINE][NEWLINE]The first civilization to cause Repercussions permanently becomes The Ex. UA rewards against The Ex increase by 25% after relationship modifiers, but rejection risk is at least 15%, even when Friendly. This is a minimum, not an added 15%. Normal cooldown still applies after recovery.'),
('TXT_KEY_CIV5_SOFT_KITTY_HEADING_4','Hopeless Romantic'),
('TXT_KEY_CIV5_SOFT_KITTY_TEXT_4','The Hopeless Romantic replaces the Great Musician and retains its Great Work of Music ability. Select the unit beside a city belonging to a met major civilization at peace with Trent, then use its Serenade button. The performance consumes the musician and grants 125% of its normal target Concert Tour Tourism, 100 Culture, and 5 Influence with City-States allied to the target. The Ex multiplies that Tourism by a further 1.20. Hostile audiences have a 25% chance of Repercussions; the rewards and unit consumption occur even when backlash follows.'),
('TXT_KEY_CIV5_SOFT_KITTY_HEADING_5','Comfort Room'),
('TXT_KEY_CIV5_SOFT_KITTY_TEXT_5','The Comfort Room inherits the active Opera House rules and adds +1 Culture, +1 local Happiness, +1 Culture for each Great Work of Music in its city, and +10% Great Musician generation in that city.[NEWLINE][NEWLINE]During Repercussions, each Comfort Room gains +3 Culture and reduces the empire-wide Production penalty by one percentage point. Three rooms reduce it to -12%; fifteen remove it entirely. The reduction never becomes a Production bonus.'),
('TXT_KEY_CIV5_SOFT_KITTY_HEADING_6','Strategy: friendship and timing'),
('TXT_KEY_CIV5_SOFT_KITTY_TEXT_6','Seek reliable diplomatic partners early. Your song grows stronger every Era, making long-term friendships valuable throughout the game. A Friendly Ex offers the highest UA reward but always carries risk. Use Comfort Rooms to prepare for ambitious performances and reserve Hopeless Romantics for culturally resistant rivals.[NEWLINE][NEWLINE]Against Trent, diplomatic isolation denies him safe audiences. Repercussions create a temporary military and economic vulnerability, especially before his network of Comfort Rooms is established.'),
('TXT_KEY_CIV5_SOFT_KITTY_FACTOID_HEADING','Court motto'),
('TXT_KEY_CIV5_SOFT_KITTY_FACTOID_TEXT','Good people. Better cats. A kinder world, one performance at a time.'),
('TXT_KEY_SOFT_KITTY_LEADER_PEDIA','Trent, the Soft Kitty Serenader, believes an empire can be built with songs, friends and softer places. His enthusiasm occasionally exceeds the patience of his audience.'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_NAME','Trent'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER','Trent, the Soft Kitty Serenader'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_SUBTITLE','The Soft Kitty Serenader'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_LIVED','The Age of Song'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_TITLES_1','Serenader of Una Court'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_HEADING_1','An enthusiastic audience of one'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_TEXT_1','Trent arrived at the affairs of state with ginger hair, spectacles, a splendid navy coat and an absolute conviction that every diplomatic problem might yield to music. Una Court embraced his optimism, decorating its halls with roses, gold and cats.'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_HEADING_2','A court built on friendship'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_TEXT_2','His finest performances turn friendship into cultural influence. Envoys return with admiration, musicians travel abroad, and allied City-States discover that the Court remembers a friendly audience. Every Era gives his melodies a little more reach.'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_HEADING_3','The price of affection'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_TEXT_3','Not every ruler welcomes a surprise Serenade. Trent remembers the first rejection forever, naming that civilization The Ex. Later performances may be richer for their shared history, but reconciliation never quite removes the possibility of another painful reception.'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_HEADING_4','Comfort after disaster'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_TEXT_4','The Comfort Room is the Court''s practical answer to heartbreak: soft cushions, resting cats, warm music and a little productive reflection. Suffering passes. The art it inspires may travel the world.'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_FACT_1','The Ex persists through saves and reloads and can never be replaced by a later rejection.'),
('TXT_KEY_CIV5_SOFT_KITTY_LEADER_FACT_2','The Hopeless Romantic can still create a normal Great Work of Music instead of performing a Serenade.'),
('TXT_KEY_SOFT_KITTY_DAWN','Trent, Soft Kitty Serenader of Una Court, your people look to you for comfort, friendship, and song.[NEWLINE][NEWLINE]Others built their empires through conquest, intrigue, or wealth. You discovered another path: sing to them until they like you.[NEWLINE][NEWLINE]Your Serenades can turn friendship into Culture and your melodies into influence across the world. Yet affection carries risk, for not every audience welcomes your enthusiasm.[NEWLINE][NEWLINE]Pain inspires art, heartbreak inspires music, and even humiliation may one day become Tourism. Will the world embrace your song, Trent? Or will history once again deliver its Repercussions?'),
('TXT_KEY_SOFT_KITTY_ROMANTIC','Hopeless Romantic'),
('TXT_KEY_SOFT_KITTY_ROMANTIC_HELP','Replaces the Great Musician. Retains Great Works of Music. Serenade beside a met, peaceful foreign major city: 125% normal Concert Tour Tourism, +100 Culture, and +5 Influence with the target''s allied City-States. The Ex gives a further +20% Tourism. Hostile audiences risk 25% Repercussions. Consumes the unit.'),
('TXT_KEY_SOFT_KITTY_ROMANTIC_STRATEGY','Move beside a foreign major city, select this unit and press Hopeless Romantic: Serenade. Choose a culturally resistant rival or The Ex for a decisive Tourism burst. A Great Work of Music remains a useful alternative. The performance requires movement remaining.'),
('TXT_KEY_SOFT_KITTY_ROMANTIC_PEDIA','The Hopeless Romantic carries a lute, a fine coat and an inexhaustible belief in the power of a heartfelt performance. His music may outlast the applause.[NEWLINE][NEWLINE]A Serenade consumes the musician even if the audience causes backlash. Its Culture and Tourism are awarded regardless. Only a Hostile audience can trigger this unit''s 25% backlash roll; the UA''s separate minimum risk against The Ex does not apply to the unit.'),
('TXT_KEY_SOFT_KITTY_COMFORT','Comfort Room'),
('TXT_KEY_SOFT_KITTY_COMFORT_HELP','Replaces the Opera House and retains its current benefits. Adds +1 Culture, +1 local Happiness, +1 Culture per Great Work of Music in this city, and +10% Great Musician generation here. During Repercussions: +3 Culture and one percentage point less empire-wide Production penalty.'),
('TXT_KEY_SOFT_KITTY_COMFORT_STRATEGY','Build Comfort Rooms throughout the empire to support musicians and soften risky diplomatic performances. The Production protection counts each city with a Comfort Room, up to fifteen. Great Work of Music Culture is local to this city.'),
('TXT_KEY_SOFT_KITTY_COMFORT_PEDIA','Behind its navy curtains and golden doors, the Comfort Room offers cats, cushions and music to anyone recovering from a disastrous performance. Its presence turns a little of the Court''s embarrassment into Culture.[NEWLINE][NEWLINE]Comfort Rooms retain the active Community Patch Opera House baseline, including its cost, prerequisites and Great Work slots. Their recovery bonuses are temporary; their ordinary Culture, Happiness and musician benefits are permanent.'),
('TXT_KEY_SOFT_KITTY_REPERCUSSIONS','Repercussions'),
('TXT_KEY_SOFT_KITTY_COMBAT_HELP','-10% military Combat Strength while Trent recovers from Repercussions.'),
('TXT_KEY_SOFT_KITTY_MOVEMENT_HELP','-1 Movement: trained during Repercussions. Removed when Trent recovers.'),
('TXT_KEY_SOFT_KITTY_INTRO','Oh hey! Don''t worry, I''m not here to possess anyone this time.'),
('TXT_KEY_SOFT_KITTY_NEUTRAL','You don''t mind a little music, do you?'),
('TXT_KEY_SOFT_KITTY_FRIENDLY','Finally, someone who appreciates a good serenade.'),
('TXT_KEY_SOFT_KITTY_HOSTILE','I''m beginning to think you don''t appreciate my singing.'),
('TXT_KEY_SOFT_KITTY_WAR','I tried being nice. I even sang to you. This is on you.'),
('TXT_KEY_SOFT_KITTY_ATTACKED','Whoa! I hadn''t even started singing yet!'),
('TXT_KEY_SOFT_KITTY_DEFEATED','At least... it wasn''t another kick.'),
('TXT_KEY_SOFT_KITTY_ACCEPT','Music to my ears.'),
('TXT_KEY_SOFT_KITTY_REJECT','Tough crowd.'),
('TXT_KEY_SOFT_KITTY_DOF','Now this is what I call a receptive audience.'),
('TXT_KEY_SOFT_KITTY_DENOUNCED','Wow. You could''ve just asked me to stop singing.'),
('TXT_KEY_SOFT_KITTY_CITY_1','Una Court'),
('TXT_KEY_SOFT_KITTY_CITY_2','Warm Hearth'),
('TXT_KEY_SOFT_KITTY_CITY_3','Serenade Bay'),
('TXT_KEY_SOFT_KITTY_CITY_4','Rose Terrace'),
('TXT_KEY_SOFT_KITTY_CITY_5','Harmony Court'),
('TXT_KEY_SOFT_KITTY_CITY_6','Velvet Hall'),
('TXT_KEY_SOFT_KITTY_CITY_7','Soft Corner'),
('TXT_KEY_SOFT_KITTY_CITY_8','Purrington'),
('TXT_KEY_SOFT_KITTY_CITY_9','Gentle Place'),
('TXT_KEY_SOFT_KITTY_CITY_10','Golden Melody'),
('TXT_KEY_SOFT_KITTY_CITY_11','Heartbreak Hill'),
('TXT_KEY_SOFT_KITTY_CITY_12','Warm Kitty'),
('TXT_KEY_SOFT_KITTY_CITY_13','Moonlit Terrace'),
('TXT_KEY_SOFT_KITTY_CITY_14','Comfort Court'),
('TXT_KEY_SOFT_KITTY_CITY_15','Second Verse');

INSERT INTO Civilization_CityNames (CivilizationType,CityName)
SELECT 'CIVILIZATION_TRENT_SOFT_KITTY',Tag FROM Language_en_US WHERE Tag LIKE 'TXT_KEY_SOFT_KITTY_CITY_%'
ORDER BY CAST(SUBSTR(Tag,25) AS INTEGER);
INSERT INTO Civilization_SpyNames (CivilizationType,SpyName)
SELECT 'CIVILIZATION_TRENT_SOFT_KITTY',SpyName FROM Civilization_SpyNames WHERE CivilizationType='CIVILIZATION_AMERICA';

UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_INTRO',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_FIRST_GREETING';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_NEUTRAL',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_GREETING_NEUTRAL_HELLO';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_FRIENDLY',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_GREETING_POLITE_HELLO';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_HOSTILE',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_GREETING_HOSTILE_HELLO';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_WAR',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_DOW_GENERIC';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_ATTACKED',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_ATTACKED_HOSTILE';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_DEFEATED',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType='RESPONSE_DEFEATED';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_ACCEPT',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType IN ('RESPONSE_TRADE_ACCEPT_ACCEPTABLE','RESPONSE_TRADE_ACCEPT_GENEROUS');
UPDATE Diplomacy_Responses SET Response='TXT_KEY_SOFT_KITTY_REJECT',Bias=1 WHERE LeaderType='LEADER_TRENT_SOFT_KITTY' AND ResponseType IN ('RESPONSE_TRADE_REJECT_INSULTING','RESPONSE_TRADE_REJECT_UNACCEPTABLE');
INSERT INTO Diplomacy_Responses (LeaderType,ResponseType,Response,Bias) VALUES
('LEADER_TRENT_SOFT_KITTY','RESPONSE_WORK_WITH_US_YES','TXT_KEY_SOFT_KITTY_DOF',1),
('LEADER_TRENT_SOFT_KITTY','RESPONSE_RESPONSE_TO_BEING_DENOUNCED','TXT_KEY_SOFT_KITTY_DENOUNCED',1);
